    /// JMPLE 03 [2 datoshi]
    /// THROW [512 datoshi]
    /// RET [0 datoshi]
    /// </remarks>
    [DisplayName("sign")]
    public abstract BigInteger? Sign(BigInteger? a);

    #endregion
}
